/** Lat/lng to the map's viewBox. */
export function projectCity(m: CityMap, lat: number, lng: number) {
  const [s, w, n, e] = m.bbox;
  return { x: ((lng - w) / (e - w)) * m.w, y: ((n - lat) / (n - s)) * m.h };
}
